import 'dart:io'; import 'package:just_audio/just_audio.dart';
class QuranAudioService {final AudioPlayer player=AudioPlayer();Future<void> playFile(File file) async {await player.setFilePath(file.path);await player.play();}Future<void> pause()=>player.pause();Future<void> stop()=>player.stop();Future<void> setSpeed(double speed)=>player.setSpeed(speed);Future<void> repeatFile(File file,int times) async {for(var i=0;i<times;i++){await player.setFilePath(file.path);await player.play();await player.processingStateStream.firstWhere((s)=>s==ProcessingState.completed);}}Future<void> dispose() => player.dispose();}
